// Package client holds the browser client that is built into the server
// binary.
//
// The files are not kept in this repository: they belong to crawl, and some
// are generated by its build. `make client` copies them here from a crawl
// checkout built with `make WEBTILES=y`.
//
//   - static/ and templates/ do not depend on the crawl version.
//   - game_data/ does: it is the client for that crawl build, used for games
//     whose client_path does not exist on disk.
//   - games.d/ is the stock game list, used when the server path has none.
//   - version.txt is the crawl version all of this came from.
package client

import "embed"

//go:embed static templates game_data games.d version.txt
var FS embed.FS
